import{_ as e,o,c as a,aa as d}from"./chunks/framework.BAs_AphD.js";const n="/buildary-help-preview/academy/img/vystupy-deniku/08.webp",s="/buildary-help-preview/media/cs/diary/prehledy_new.png",r="/buildary-help-preview/media/cs/diary/prehledy_pocasi.png",g=JSON.parse('{"title":"Přehledy","description":"","frontmatter":{"title":"Přehledy","wiki":"cs:diary:reports"},"headers":[],"relativePath":"diary/reports.md","filePath":"diary/reports.md","lastUpdated":1794209661000}'),l={name:"diary/reports.md"};function i(p,t,h,b,u,c){return o(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="prehledy" tabindex="-1">Přehledy <a class="header-anchor" href="#prehledy" aria-label="Permalink to &quot;Přehledy&quot;">​</a></h1><p>Přehledy sčítají data deníku za zvolené období do tabulky – například kolik lidí kterého dodavatele bylo na stavbě v jednotlivých dnech, kolik hodin pracovaly stroje nebo kdy klesla teplota pod zvolenou hodnotu.</p><p>Krok za krokem: <a href="/buildary-help-preview/akademie/vystupy-deniku">Najít zápis, vytisknout nebo stáhnout deník</a> v Akademii.</p><h2 id="zobrazit-prehled" tabindex="-1">Zobrazit přehled <a class="header-anchor" href="#zobrazit-prehled" aria-label="Permalink to &quot;Zobrazit přehled&quot;">​</a></h2><p>V levém panelu otevřete <strong>Přehledy</strong> a nastavte:</p><table tabindex="0"><thead><tr><th>Pole</th><th>Co určuje</th></tr></thead><tbody><tr><td><strong>Doména</strong>, <strong>Projekt</strong> (stavba), <strong>Deník</strong></td><td>ze kterého deníku se data berou</td></tr><tr><td><strong>Sekce přehledu</strong></td><td>sekce denních záznamů, například Osoby na staveništi</td></tr><tr><td><strong>Seskupovat podle</strong></td><td>jak podrobně se data sečtou (viz níže)</td></tr><tr><td><strong>Období od</strong>, <strong>Období do</strong></td><td>rozsah dat; podle jeho délky se volí i sloupce (viz níže)</td></tr><tr><td><strong>Zobrazit</strong></td><td>co se sčítá: <strong>Hodiny</strong>, <strong>Počet</strong> nebo <strong>Množství</strong></td></tr></tbody></table><p>Pak klikněte na <strong>Zobrazit</strong>.</p><figure class="shot" style="--w:760px;"><img src="'+n+'" alt="Přehled Osoby na staveništi seskupený podle dodavatele za jeden měsíc" loading="lazy"></figure><div class="info custom-block"><p class="custom-block-title">Po každé změně</p><p>Po každé změně nastavení klikněte znovu na <strong>Zobrazit</strong>, jinak tabulka ukazuje stará data.</p></div><h2 id="seskupeni" tabindex="-1">Seskupení <a class="header-anchor" href="#seskupeni" aria-label="Permalink to &quot;Seskupení&quot;">​</a></h2><p>Každá sekce nabízí jiné možnosti seskupení podle toho, jaká data obsahuje. Například u <strong>Osob na staveništi</strong> je jich pět: nejhrubší je <strong>Dodavatel</strong>, nejpodrobnější <strong>Dodavatel, Profese, Příjmení a jméno</strong> – ten obsahuje i mezisoučty za každou úroveň.</p><figure class="shot" style="--w:600px;"><img src="'+s+'" alt="Přehled Osoby na staveništi seskupený podle dodavatele, profese a jména s mezisoučty" loading="lazy"></figure><h2 id="co-se-scita" tabindex="-1">Co se sčítá <a class="header-anchor" href="#co-se-scita" aria-label="Permalink to &quot;Co se sčítá&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Volba</th><th>U kterých sekcí</th><th>Význam</th></tr></thead><tbody><tr><td><strong>Hodiny</strong></td><td>osoby a stroje</td><td>součet odpracovaných hodin</td></tr><tr><td><strong>Počet</strong></td><td>téměř všechny</td><td>u jednotlivé osoby počet dní, kdy byla na stavbě; u seskupených řádků počet osob v daném dni</td></tr><tr><td><strong>Množství</strong></td><td>materiály a práce</td><td>součet množství</td></tr></tbody></table><p><strong>Počet</strong> nezohledňuje hodiny: člověk se započítá jednou, ať pracoval hodinu, nebo celý den.</p><h2 id="obdobi-a-sloupce" tabindex="-1">Období a sloupce <a class="header-anchor" href="#obdobi-a-sloupce" aria-label="Permalink to &quot;Období a sloupce&quot;">​</a></h2><p>Podle délky období se automaticky volí, co představuje jeden sloupec:</p><table tabindex="0"><thead><tr><th>Délka období</th><th>Sloupce</th><th>Nejdelší období v tomto členění</th></tr></thead><tbody><tr><td>kratší než 32 dní</td><td>dny</td><td>1 měsíc</td></tr><tr><td>32 dní až 36 měsíců</td><td>měsíce</td><td>3 roky</td></tr><tr><td>delší než 36 měsíců</td><td>roky</td><td>bez omezení</td></tr></tbody></table><h2 id="prehled-pocasi" tabindex="-1">Přehled počasí <a class="header-anchor" href="#prehled-pocasi" aria-label="Permalink to &quot;Přehled počasí&quot;">​</a></h2><p>Sekce <strong>Počasí</strong> funguje jinak: nesčítá, ale vyhledá měření, kdy počasí splnilo zadanou podmínku. V poli <strong>Filtrovat podle</strong> zvolte veličinu (například <strong>Teplota</strong>), v <strong>Zobrazit</strong> zvolte <strong>Menší</strong> nebo <strong>Větší</strong> a do pole <strong>Hodnota</strong> napište mez. Takto třeba najdete všechna měření, kdy byla teplota nižší než 5 °C.</p><figure class="shot" style="--w:760px;"><img src="'+r+'" alt="Přehled Počasí filtrovaný na teplotu menší než 5 °C" loading="lazy"></figure><p>Celý deník nebo jeho data si stáhnete podle stránky <a href="/buildary-help-preview/diary/download">Tisk a export deníku</a>.</p>',22)])])}const y=e(l,[["render",i]]);export{g as __pageData,y as default};
